import 'dart:async';

import 'package:decimal/decimal.dart';
import 'package:flutter/foundation.dart';
import 'package:isar_community/isar.dart';

import '../db/isar/main_db.dart';
import '../models/isar/models/isar_models.dart';
import '../networking/http.dart';
import '../wallets/crypto_currency/crypto_currency.dart';
import 'price.dart';

class PriceService extends ChangeNotifier {
  late final String baseTicker;
  Future<Set<String>> get tokenContractAddressesToCheck async =>
      (await MainDB.instance.getEthContracts().addressProperty().findAll())
          .toSet();
  Future<Set<String>> get solTokenContractAddressesToCheck async =>
      (await MainDB.instance.getSolContracts().addressProperty().findAll())
          .toSet();
  final Duration updateInterval = const Duration(seconds: 60);

  Timer? _timer;
  final Map<CryptoCurrency, ({Decimal value, double change24h})> _cachedPrices =
      {};

  final Map<String, ({Decimal value, double change24h})> _cachedTokenPrices =
      {};

  final _priceAPI = PriceAPI(HTTP());

  /// A price of zero means "this coin is not listed on the price API", not
  /// "this coin is worth nothing". The upstream cache stores that as a real
  /// record, so every `price != null` check in the UI passed and rendered a
  /// fabricated "+0.00 USD" on every amount. BFX is unlisted, so that was the
  /// whole app.
  ///
  /// Normalised here rather than at the ~37 call sites: the callers already
  /// treat null as "no price and show nothing", which is exactly right.
  ({Decimal value, double change24h})? _orNullIfUnpriced(
    ({Decimal value, double change24h})? cached,
  ) => (cached == null || cached.value <= Decimal.zero) ? null : cached;

  ({Decimal value, double change24h})? getPrice(CryptoCurrency coin) =>
      _orNullIfUnpriced(_cachedPrices[coin]);

  ({Decimal value, double change24h})? getTokenPrice(String contractAddress) =>
      _orNullIfUnpriced(_cachedTokenPrices[contractAddress.toLowerCase()]);

  final Map<CryptoCurrency, List<double>> _cachedSparklines = {};

  /// 7-day hourly price series, or null when the coin has no market.
  ///
  /// Gated on getPrice for the same reason that exists: an unlisted coin caches
  /// a zero price, and a chart drawn from that would be a flat line at zero —
  /// a made-up claim rather than an absence. Callers render nothing on null.
  List<double>? getSparkline(CryptoCurrency coin) {
    if (getPrice(coin) == null) return null;
    final series = _cachedSparklines[coin];
    return (series != null && series.length > 1) ? series : null;
  }

  final Map<CryptoCurrency, double> _cachedSparklineSpans = {};

  /// Price series for the hero chart's range selector, with the span it really
  /// covers.
  ///
  /// Returns null for "this coin has no chart", which the caller must render
  /// as nothing. It is NOT the same as "still loading", and conflating the two
  /// is what left BFX on a spinner that never resolved: 24H and 30D went to
  /// CoinGecko, which does not list BFX, so they returned null forever.
  ///
  /// spanHours is what the data actually covers, not what was asked for. A
  /// market younger than the requested range returns everything it has, and
  /// labelling that by the range would date the oldest point wrongly.
  ///
  /// Same unlisted-coin gate as [getSparkline]: no market, no chart, never a
  /// flat line at zero.
  Future<({List<double> series, double spanHours})?> getRangeSeries(
    CryptoCurrency coin,
    int days,
  ) async {
    if (getPrice(coin) == null) return null;

    // 7 days costs nothing for any coin: the price poll already carries it.
    // Checked before the BFX branch on purpose, so opening a wallet does not
    // fire an extra request for the range the hero opens on.
    if (days == 7) {
      final s = getSparkline(coin);
      if (s == null) return null;
      return (series: s, spanHours: _cachedSparklineSpans[coin] ?? 168.0);
    }

    if (_isBitfinite(coin)) {
      final r = await _priceAPI.getBitfiniteRange(
        days: days,
        baseCurrency: baseTicker,
      );
      if (r == null || r.series.length < 2) return null;
      return (series: r.series, spanHours: r.spanHours ?? days * 24.0);
    }

    final s = await _priceAPI.getMarketChart(
      coin: coin,
      days: days,
      baseCurrency: baseTicker,
    );
    if (s == null || s.length < 2) return null;
    // CoinGecko honours the window it is given, so the range asked for is the
    // range returned.
    return (series: s, spanHours: days * 24.0);
  }

  /// BFX is the one coin served by our own endpoint rather than CoinGecko, so
  /// it is the one coin whose ranges do not come from getMarketChart. Matched
  /// on prettyName because that is what the price fetch already keys on, and
  /// the testnet coin ("tBitFinite") cannot collide with it.
  bool _isBitfinite(CryptoCurrency coin) => coin.prettyName == "BitFinite";

  PriceService(this.baseTicker);

  Future<void> updatePrice() async {
    final priceMap = await _priceAPI.getPricesAnd24hChange(
      baseCurrency: baseTicker,
    );

    _cachedSparklines
      ..clear()
      ..addAll(_priceAPI.sparklines);
    _cachedSparklineSpans
      ..clear()
      ..addAll(_priceAPI.sparklineSpanHours);

    bool shouldNotify = false;
    for (final map in priceMap.entries) {
      if (_cachedPrices[map.key] != map.value) {
        _cachedPrices[map.key] = map.value;
        shouldNotify = true;
      }
    }

    final _tokenContractAddressesToCheck = await tokenContractAddressesToCheck;

    if (_tokenContractAddressesToCheck.isNotEmpty) {
      final tokenPriceMap = await _priceAPI.getPricesAnd24hChangeForEthTokens(
        contractAddresses: _tokenContractAddressesToCheck,
        baseCurrency: baseTicker,
      );

      for (final map in tokenPriceMap.entries) {
        if (_cachedTokenPrices[map.key] != map.value) {
          _cachedTokenPrices[map.key] = map.value;
          shouldNotify = true;
        }
      }
    }

    final _solTokenContractAddressesToCheck = await solTokenContractAddressesToCheck;

    if (_solTokenContractAddressesToCheck.isNotEmpty) {
      final solTokenPriceMap = await _priceAPI.getPricesAnd24hChangeForSolTokens(
        contractAddresses: _solTokenContractAddressesToCheck,
        baseCurrency: baseTicker,
      );

      for (final map in solTokenPriceMap.entries) {
        if (_cachedTokenPrices[map.key] != map.value) {
          _cachedTokenPrices[map.key] = map.value;
          shouldNotify = true;
        }
      }
    }

    if (shouldNotify) {
      notifyListeners();
    }
  }

  void cancel() {
    _timer?.cancel();
    _timer = null;
  }

  void start(bool rightAway) {
    if (rightAway) {
      updatePrice();
    }
    _timer?.cancel();
    _timer = Timer.periodic(updateInterval, (_) {
      updatePrice();
    });
  }

  @override
  void dispose() {
    cancel();
    super.dispose();
  }
}
